import java.math.*;import java.util.*;public class TestMain{static void eq(long a,long b){if(a!=b)throw new AssertionError(a+" != "+b);}public static void main(String[]a){TaxTable t=new TaxTable(Map.of("A",new BigDecimal("0.10"),"B",new BigDecimal("0.075")));TaxCalculator c=new TaxCalculator(t);eq(c.taxCents(List.of(new Line("0.05","A"),new Line("0.05","A"))),1);eq(c.taxCents(List.of(new Line("10.00","A"),new Line("10.00","B"))),175);eq(c.taxCents(List.of(new Line("0.05","A"))),0);try{c.taxCents(List.of(new Line("-1","A")));throw new AssertionError();}catch(IllegalArgumentException e){}System.out.println("OK");}}
